const fs = require("node:fs");
const path = require("node:path");
const { projectRoot } = require("./local-single-user-runtime.cjs");

const sourceSchemaPath = path.join(projectRoot, "prisma", "schema.prisma");
const targetSchemaPath = path.join(projectRoot, "prisma", "schema.local.prisma");

function buildLocalSchemaContent(source) {
  return [
    "// Auto-generated from prisma/schema.prisma for local-single-user mode.",
    "// Do not edit this file by hand; update the source schema or generator instead.",
    source
      .replace('provider = "postgresql"', 'provider = "sqlite"')
      .replace(/Json\s+@default\("\{\}"\)/g, "Json")
      .replace(/@db\.Decimal\(10,\s*2\)/g, ""),
    "",
  ].join("\n");
}

function generateLocalSchema() {
  const source = fs.readFileSync(sourceSchemaPath, "utf8").replace(/^\uFEFF/, "");
  const target = buildLocalSchemaContent(source);
  fs.writeFileSync(targetSchemaPath, target, "utf8");
  return targetSchemaPath;
}

if (require.main === module) {
  const outputPath = generateLocalSchema();
  console.log(`已生成本地 SQLite Prisma schema: ${outputPath}`);
}

module.exports = {
  buildLocalSchemaContent,
  generateLocalSchema,
  sourceSchemaPath,
  targetSchemaPath,
};
